#!/usr/bin/env bash
# C3 安全账 AI 配图：封面（21:9）+ 02 目标函数缺项 + 04 检查/执行分离
cd "$(dirname "$0")"
source ~/.bash_env 2>/dev/null || true
python3 ../../scripts/yairouter_img.py --prompt "A cinematic wide banner, dark navy-blue gradient background fading to near-black at the edges. Two lines of glowing golden Chinese text centered horizontally across the full width, no left-right split: line one reads 你定的规矩, line two reads 压缩后还剩几条. The gold glow is bright but the background stays dimmed and recedes behind the text. No other text, no letters, no numbers, no watermark, no human figures anywhere in the frame. Minimal, elegant, high contrast between the golden glow and the dark background." --size 21:9 --output-dir . --filename 00-cover.png > /tmp/c3_cover.log 2>&1
python3 ../../scripts/yairouter_img.py --prompt "A minimalist conceptual illustration on a clean off-white background, no text, no numbers, no letters. Center: a funnel-shaped compressor device with a glowing task-success meter dial on its body. A long scroll of conversation history enters the funnel from the left; a short compact summary card exits on the right. Floating just outside the funnel, untethered and unconnected: a small shield with a lock symbol and a small checklist card with checkmarks, drawn in muted blue-grey, visually excluded from the machine. Soft flat illustration style, muted navy blue and gold accent palette, generous negative space." --output-dir . --filename 02-lambda.png > /tmp/c3_lambda.log 2>&1
python3 ../../scripts/yairouter_img.py --prompt "A minimalist conceptual illustration on a clean off-white background, no text, no numbers, no letters. Split composition: on the left, a magnifying-glass inspector examines a tall stack of loose document pages, each page showing a small benign icon. In the middle, a dark funnel compresses the pages into a single small summary card. On the right, an executor robot arm acts on that summary card, and the card now shows one merged bold instruction symbol formed from fragments of the left pages. A subtle visual gap between the inspection zone and the execution zone, with the funnel sitting alone in the gap. Soft flat illustration style, muted navy blue and gold accent palette, generous negative space." --output-dir . --filename 04-relinking.png > /tmp/c3_relink.log 2>&1
echo ALL_DONE > /tmp/c3_ai_done
